const ZINC_INFO={id:"zinc-distillation",title:"Zinc Distillation — The Zawar Process",originRegion:"Zawar, Rajasthan, India",eraOrigin:"Zinc smelting from c. 9th Century BCE; Distillation process refined by 12th–14th Century CE",quickStats:[{label:"Site",value:"Zawar Mines, Rajasthan",icon:"⛰️"},{label:"Process",value:"Downward (Descending) Distillation",icon:"🔻"},{label:"Zinc Boiling Point",value:"907°C",icon:"🌡️"},{label:"Retort Material",value:"Fireclay Vessels",icon:"🏺"},{label:"World First",value:"Earliest Industrial-Scale Zinc Production",icon:"🥇"},{label:"Recognized By",value:"UNESCO / Global Metallurgy Historians",icon:"🌍"}]},HISTORY_TEXT={title:"The World's First Industrial Zinc Production",paragraphs:["Zinc is uniquely difficult to smelt using conventional methods: at the temperature needed to reduce zinc oxide to metal, zinc itself is already a vapor. Any smelter using an open furnace, like those used for iron or copper, would simply lose the zinc as gas into the air. Solving this problem required an entirely different approach — distillation.","At Zawar, in present-day Rajasthan, archaeological and metallurgical evidence shows that Indian metalworkers were smelting zinc ore on an industrial scale by at least the 12th century CE, building on ore-roasting and smelting traditions in the region that reach back centuries earlier. Zawar is widely regarded by historians of metallurgy as the site of the world's earliest large-scale zinc production.","The breakthrough was the 'downward distillation' technique: ore was packed into sealed clay retorts with a narrow condenser tube pointing downward into a collection vessel buried in the ground below. As the retort was heated, zinc vapor was driven off, traveled down the tube away from the open air and its oxygen, and condensed into liquid metal in the cooler chamber beneath — a design that prevented the vapor from re-oxidizing before it could be captured.","Thousands of discarded retorts found at Zawar attest to a sustained, large-scale industry that supplied zinc metal used across India and, via trade networks, well beyond it, centuries before comparable distillation processes appeared in Europe."]},PROCESS_STEPS=[{title:"1. Charging the Retort",description:"Crushed zinc ore, mixed with an organic reducing agent, is packed into a sealed, bottle-shaped fireclay retort with a narrow-necked condenser tube fitted at its base."},{title:"2. Furnace Heating",description:"Rows of retorts are stacked mouth-down in a furnace and heated to roughly 1,000°C — hot enough to reduce zinc oxide to metal, which immediately vaporizes at this temperature."},{title:"3. Downward Vapor Flow",description:"Because the condenser tube points downward and away from open air, the zinc vapor is forced away from atmospheric oxygen instead of escaping upward and burning off, as it would in an open furnace."},{title:"4. Condensation & Collection",description:"The vapor travels down into a cooler clay condenser vessel buried below the furnace, where it condenses back into liquid zinc metal and is collected once the process is complete."}],SCIENTIFIC_PRINCIPLES=[{title:"Boiling Point Below Reduction Temperature",description:"Zinc boils at 907°C, well below the ~1,200°C needed for some other metal smelting — meaning zinc is a vapor the instant it is reduced, unlike iron or copper which stay solid or liquid."},{title:"Oxidation Avoidance",description:"Zinc vapor reacts almost instantly with atmospheric oxygen to reform zinc oxide. Directing the vapor downward, away from air, was essential to capturing metallic zinc rather than losing it as smoke."},{title:"Sealed Retort Design",description:"The airtight, bottle-shaped retort kept the reducing atmosphere inside contained, preventing oxygen from re-entering and interrupting the reduction reaction."},{title:"Controlled Condensation",description:"A cooler condensation zone, physically separated from the hot reaction zone, allowed the vapor to cool below 907°C and solidify into usable metal."}],APPLICATIONS=[{title:"Galvanization",description:"Zinc coatings protect steel and iron from rust in everything from car bodies to construction beams — a direct descendant of zinc's industrial availability."},{title:"Brass Alloys",description:"Combining zinc with copper produces brass, used across musical instruments, plumbing fittings, and decorative hardware."},{title:"Batteries",description:"Zinc is a key electrode material in alkaline and zinc-carbon batteries, prized for its reactivity and abundance."},{title:"Zinc Oxide Applications",description:"Zinc oxide, derived from refined zinc, is used in sunscreens, ointments, rubber manufacturing, and ceramics."},{title:"Modern Distillation Industry",description:"The core principle pioneered at Zawar — vaporizing and re-condensing a metal away from oxidizing conditions — still underlies industrial vacuum and vapor-phase metal refining today."},{title:"Nutritional Supplementation",description:"Zinc compounds derived from refined metal are essential in dietary supplements and fortified foods worldwide."}],REFERENCES=[{text:"Craddock, P. T. — 'Zinc in India' (in '2000 Years of Zinc and Brass', British Museum).",link:"#"},{text:"Willies, L. — 'Ancient Zinc Smelting in Rajasthan' (Historical Metallurgy Society).",link:"#"},{text:"Werner, O. & Willies, L. — 'The Chronology of Zinc Smelting in India.'",link:"#"},{text:"Archaeological Survey of India — Zawar Mines excavation reports.",link:"#"}];